const quizTypeLabels = {
  "escolha_múltipla": "Escolha múltipla",
  "verdadeiro_falso": "Verdadeiro/Falso",
  "associação": "Associação",
  "cronológica": "Cronologia",
  "causas_consequências": "Causas e consequências"
};

function enrichQuizBank() {
  Object.entries(eras).forEach(([key, era]) => {
    const existing = Array.isArray(era.quiz) ? era.quiz : [era.quiz];
    const enrichedExisting = existing.map((quiz, index) => ({
      type: quiz.type || "escolha_múltipla",
      difficulty: quiz.difficulty || ["fácil", "média", "difícil"][index % 3],
      explanation: quiz.explanation || `A resposta correta é “${quiz.options[quiz.answer]}”. Esta opção enquadra melhor o contexto de ${era.title} e evita uma leitura simplista do processo histórico.`,
      ...quiz
    }));
    era.quiz = [...enrichedExisting, ...(quizExtensions[key] || [])];
  });
}

enrichQuizBank();


